const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Smith Island location (Chesapeake Bay, Maryland)
  const smithIsland = ee.Geometry.Point([-76.03, 37.97]).buffer(3000);

  // 2. Data acquisition for 1999 (Landsat 5)
  const col1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(smithIsland)
    .filterDate('1999-05-01', '1999-10-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const size1999 = col1999.size().getInfo();
  console.log(`1999 Images found: ${size1999}`);

  if (size1999 === 0) {
    console.log('No images for 1999');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data acquisition for 2019 (Landsat 8)
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(smithIsland)
    .filterDate('2019-05-01', '2019-10-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images found: ${size2019}`);

  if (size2019 === 0) {
    console.log('No images for 2019');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function for Landsat
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask);
  }

  // 5. Calculate MNDWI and get land pixels
  function addMNDWI_L5(image) {
    const green = image.select('SR_B2').multiply(0.0000275).add(-0.2);
    const swir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
    return image.addBands(mndwi);
  }

  function addMNDWI_L8(image) {
    const green = image.select('SR_B3').multiply(0.0000275).add(-0.2);
    const swir = image.select('SR_B6').multiply(0.0000275).add(-0.2);
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // 6. Process 1999 data
  const img1999 = col1999.map(maskL5sr).map(addMNDWI_L5).median();
  const land1999 = img1999.select('MNDWI').lt(0);

  const count1999 = land1999.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: smithIsland,
    scale: 1000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`1999 valid pixels: ${count1999}`);

  if (count1999 === 0) {
    console.log('No valid pixels for 1999');
    console.log('<answer>C2</answer>');
    return;
  }

  const landArea1999 = land1999.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: smithIsland,
    scale: 1000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  // 7. Process 2019 data
  const img2019 = col2019.map(maskL8sr).map(addMNDWI_L8).median();
  const land2019 = img2019.select('MNDWI').lt(0);

  const count2019 = land2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: smithIsland,
    scale: 1000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`2019 valid pixels: ${count2019}`);

  if (count2019 === 0) {
    console.log('No valid pixels for 2019');
    console.log('<answer>C2</answer>');
    return;
  }

  const landArea2019 = land2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: smithIsland,
    scale: 1000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  // 8. Validation and final answer
  if (landArea1999 === null || landArea2019 === null || isNaN(landArea1999) || isNaN(landArea2019)) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Land pixels 1999: ${landArea1999.toFixed(0)}`);
  console.log(`Land pixels 2019: ${landArea2019.toFixed(0)}`);

  const change = ((landArea2019 - landArea1999) / landArea1999 * 100).toFixed(1);
  console.log(`Change: ${change}%`);

  if (landArea2019 < landArea1999) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
